<div class="page-heading"><div><p class="eyebrow">BACKSTAGE / MERCHANDISE</p><h1><?=e($titles[$view])?></h1><p class="lead">Real products, clear stock, and a consistent customer experience.</p></div></div>
<nav class="store-admin-nav" aria-label="Store administration"><?php foreach(['products'=>['Products','index.php'],'categories'=>['Categories','categories.php'],'customers'=>['Customers','customers.php'],'settings'=>['Store settings','settings.php']] as $k=>[$label,$route]):if(in_array($k,['settings','customers'],true)&&!Spirit\Permissions::allows($user,'owner')){continue;}?><a href="<?=e(app_url('admin/shop/'.$route))?>" <?=$view===$k?'aria-current="page"':''?>><?=e($label)?></a><?php endforeach;?></nav>
<?php View::notice($error);if($view==='products'):
