<section class="panel"><div class="button-row"><a class="button" href="<?=e(app_url('admin/shop/edit.php'))?>">Add product</a><a class="button secondary" href="<?=e(app_url('shop/'))?>" target="_blank" rel="noopener">View public catalog</a></div><form class="shop-filter" method="get"><label>Search products<input name="q" value="<?=e($search)?>"></label><button class="button" type="submit">Search</button></form><div class="table-scroll"><table class="content-table"><thead><tr><th>Product</th><th>Publication</th><th>Variants</th><th>Manage</th></tr></thead><tbody><?php foreach($listing['items'] as $item):?><tr><td><?=e($item['data']['name'])?><small>/<?=e($item['slug'])?></small></td><td><?=$item['published_json']?'Published + private draft':'Private draft'?></td><td><?=count($item['variants'])?></td><td><a href="<?=e(app_url('admin/shop/edit.php?id='.$item['id']))?>">Edit product</a><br><a href="<?=e(app_url('admin/shop/variants.php?id='.$item['id']))?>">Variants & stock</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$listing['items']):?><p>No products yet. Add a draft, upload real photographs and create variants before publishing.</p><?php endif;Storefront::pager($listing,'admin/shop/',['q'=>$search]);?></section>
<?php elseif($view==='edit'):$d=$product['data']??['name'=>'','description'=>'','size_guide'=>'','category_id'=>0,'image_ids'=>[]];?>
<form method="post" class="editor-layout"><section class="panel form-stack"><?=csrf_field()?><input type="hidden" name="revision" value="<?=$product['revision']??1?>"><?php StoreAdmin::field('name','Product name',$d['name'],'text',160);StoreAdmin::field('slug','Permanent URL name',$product['slug']??'','text',90);StoreAdmin::field('description','Description',$d['description'],'textarea',10000);StoreAdmin::field('size_guide','Size / care guide',$d['size_guide'],'textarea',4000);?>
<label class="field-stack">Category<select name="category_id"><option value="0">Uncategorized</option><?php foreach(Catalog::categories() as $c):?><option value="<?=$c['id']?>" <?=(int)$d['category_id']===(int)$c['id']?'selected':''?>><?=e($c['name'].(!(int)$c['active']?' (hidden)':''))?></option><?php endforeach;?></select></label><label class="field-stack">Product photographs (up to eight)<select name="image_ids[]" multiple size="6"><?php foreach(Media::all('image') as $m):?><option value="<?=$m['id']?>" <?=in_array((int)$m['id'],$d['image_ids'],true)?'selected':''?>>#<?=$m['id']?> · <?=e($m['original_name'])?></option><?php endforeach;?></select><small>Upload approved photographs in Media library first. The first selected photograph is the main image. Product images are contained, not cropped.</small></label><label class="checkbox-label"><input type="checkbox" name="approved" value="1">I confirm these are real, approved products and descriptions.</label></section><aside class="panel editor-actions"><h2>Publication</h2><button class="button secondary" name="action" value="draft">Save private draft</button><button class="button" name="action" value="publish">Publish approved product</button><?php if($product):?><button class="button outline" name="action" value="unpublish">Remove from public catalog</button><a class="button secondary" href="<?=e(app_url('admin/shop/variants.php?id='.$id))?>">Variants & inventory</a><?php endif;?><p class="small muted">Draft edits do not change the public snapshot. Active prices and stock are managed separately and take effect immediately.</p></aside></form>
<?php elseif($view==='variants'):$variants=Catalog::variants($id);?>
<p><a href="<?=e(app_url('admin/shop/edit.php?id='.$id))?>">← <?=e($product['data']['name'])?></a></p><div class="notice info">Variant prices and availability are live operational settings. New variants start with zero stock; record a stock adjustment to add inventory. Stock is not reserved by a bag.</div>
<?php foreach([...$variants,null] as $v):?><section class="panel variant-panel"><h2><?=$v?e($v['sku']):'Add a variant'?></h2><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="action" value="variant"><input type="hidden" name="variant_id" value="<?=$v['id']??0?>"><input type="hidden" name="revision" value="<?=$v['revision']??1?>"><div class="store-fields"><?php StoreAdmin::field('sku','SKU',$v['sku']??'','text',64);StoreAdmin::field('size_label','Size',$v['size_label']??'','text',40);StoreAdmin::field('color_label','Color',$v['color_label']??'','text',60);StoreAdmin::field('price','Unit price (USD)',$v?Money::decimal((int)$v['price_cents']):'','text',12);?></div><label class="checkbox-label"><input type="checkbox" name="active" value="1" <?=!$v||(int)$v['active']?'checked':''?>>Available variant</label><button class="button" type="submit">Save variant</button></form>
<?php if($v):?><div class="inventory-box"><h3>Current stock: <?=$v['stock']?></h3><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="action" value="stock"><input type="hidden" name="variant_id" value="<?=$v['id']?>"><input type="hidden" name="revision" value="<?=$v['revision']?>"><input type="hidden" name="nonce" value="<?=e(bin2hex(random_bytes(32)))?>"><div class="store-fields"><?php StoreAdmin::field('delta','Quantity to add / subtract','','number');StoreAdmin::field('reason','Adjustment reason','','text',300);?></div><button class="button secondary" type="submit">Record stock adjustment</button></form><?php $q=$db->prepare('SELECT quantity_delta,stock_after,reason,created_at FROM '.Database::table('inventory_adjustments').' WHERE variant_id=? ORDER BY id DESC LIMIT 5');$q->execute([$v['id']]);?><div class="inventory-history"><?php foreach($q as $movement):?><p><strong><?=e(($movement['quantity_delta']>0?'+':'').$movement['quantity_delta'])?></strong> → <?=$movement['stock_after']?> · <?=e($movement['reason'])?><small><?=e($movement['created_at'])?> UTC</small></p><?php endforeach;?></div></div><?php endif;?></section><?php endforeach;?>
<?php elseif($view==='categories'):foreach([...Catalog::categories(),null] as $c):?><section class="panel"><h2><?=$c?e($c['name']):'New category'?></h2><form method="post" class="form-stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']??0?>"><input type="hidden" name="revision" value="<?=$c['revision']??1?>"><div class="store-fields"><?php StoreAdmin::field('name','Category name',$c['name']??'','text',120);StoreAdmin::field('slug','URL name',$c['slug']??'','text',90);?></div><?php StoreAdmin::field('description','Description',$c['description']??'','textarea',2000);?><label class="checkbox-label"><input type="checkbox" name="active" value="1" <?=!$c||(int)$c['active']?'checked':''?>>Show this category and its published products</label><button class="button" type="submit">Save category</button></form></section><?php endforeach;?>
<?php elseif($view==='settings'):$options=Catalog::options();?>
<section class="panel"><form method="post" class="form-stack"><?=csrf_field()?><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?=$options['enabled']?'checked':''?>>Open the published merchandise catalog</label><label class="checkbox-label"><input type="checkbox" name="accounts_enabled" value="1" <?=$options['accounts_enabled']?'checked':''?>>Enable customer registration and recovery (requires configured email)</label><?php StoreAdmin::field('intro','Store introduction',$options['intro'],'textarea',1000);?><button class="button" type="submit">Save store settings</button></form><div class="notice info">Catalog visibility is separate from payment enablement. Configure delivery rules and Authorize.net under Orders & payments before enabling checkout. Customer registration verifies email before a password is chosen.</div></section>
<?php elseif($view==='customers'):
$search=is_string($_GET['q']??null)?substr(trim($_GET['q']),0,100):'';$q=$db->prepare('SELECT COUNT(*) FROM '.Database::table('customers').' WHERE name LIKE ? OR email LIKE ?');$q->execute(['%'.$search.'%','%'.$search.'%']);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/25));$page=max(1,min($pages,(int)($_GET['page']??1)));$q=$db->prepare('SELECT id,name,email,status,verified_at,created_at FROM '.Database::table('customers').' WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 25 OFFSET '.(($page-1)*25));$q->execute(['%'.$search.'%','%'.$search.'%']);?>
<section class="panel"><form class="shop-filter" method="get"><label>Find a customer<input name="q" value="<?=e($search)?>" maxlength="100"></label><button class="button" type="submit">Search</button></form><div class="table-scroll"><table class="content-table"><thead><tr><th>Customer</th><th>Status</th><th>Access</th></tr></thead><tbody><?php foreach($q as $c):?><tr><td><?=e($c['name'])?><small><?=e($c['email'])?></small></td><td><?=e($c['status'])?></td><td><?php if($c['verified_at']):?><form method="post"><?=csrf_field()?><input type="hidden" name="customer_id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='active'?'suspended':'active'?>"><button class="button secondary" type="submit"><?=$c['status']==='active'?'Suspend access':'Restore access'?></button></form><?php else:?>Awaiting email verification<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php Storefront::pager(compact('page','pages'),'admin/shop/customers.php',['q'=>$search]);?><p class="small muted">Customer passwords, account tokens and private message bodies are never displayed here.</p></section><?php endif;?>
